do $do$ declare d jsonb := $j${"topic": {"id": "004396a5-19db-5ac6-9df6-126e61518dca", "new": true, "name": "Biology · Body systems", "summary": "Grade 9 Biology", "sort": 3, "parent": "31ac6b73-081c-5adc-a181-79eca8995b86", "programme": "MYP 4"}, "anchor": "/g9-unit1-cell-theory/", "lessons": [{"id": "c811710f-5015-592e-8118-a7b048ee4c9c", "ext": "G9-BIO-BODY-L1", "title": "Biology · Body systems · Lesson 1: The respiratory system: parts and their jobs", "summary": "MYP 4 · Biology · Body systems", "url": "/g9-bio-body-1/", "max": 27, "sort": 11, "msort": 87, "csort": 14, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 5, "n": 5, "ans": ["4th", "1st", "5th", "2nd", "3rd"], "tip": "The tubes get narrower as you go deeper."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 6, "n": 6, "ans": ["Nasal cavity", "Trachea", "Bronchiole", "Alveolus", "Ribs", "Diaphragm"], "tip": "Follow the air from the outside in."}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 2, "pts": [["open", "not collapse", "stop it collapsing", "prevent collapse", "does not close"], ["air", "pressure", "breathe in", "flow"]], "tips": ["What would happen to a soft tube when air is sucked through it?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 6, "n": 6, "ans": ["Breathing", "Respiration", "Gas exchange", "Breathing", "Respiration", "Gas exchange"], "tip": "Is it a movement of air, a movement of gases across a wall, or a reaction in cells?"}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 2, "pts": [["air", "in and out", "into and out", "ventilation", "inhal"], ["chemical", "reaction", "release energy", "releases energy", "glucose", "cells"]], "tips": ["One is movement, one is a reaction."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q7", "max": 3, "pts": [["lungs", "alveol", "breath"], ["blood", "capillar", "red blood", "haemoglobin"], ["heart", "pump", "carried", "transport", "artery", "arteries"]], "tips": ["Lungs → blood → muscle."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 3, "pts": [["less oxygen", "lower oxygen", "thin air", "low pressure"], ["more red blood", "red blood cells", "haemoglobin"], ["fair", "advantage", "not everyone", "cannot", "altitude tent", "rules", "unfair"]], "tips": ["Less oxygen → the body adapts → is that fair?"]}]}, "models": {"1": [["Q1", "The chest and stomach move outward as you breathe in. The air goes down the trachea, into the two bronchi, the bronchioles and the alveoli in the lungs."], ["Q2", "Nasal cavity → trachea → bronchus → bronchiole → alveolus."]], "2": [["Q3", "Nasal cavity filters; trachea is held open by cartilage; bronchioles carry air to the alveoli; alveoli exchange gases; ribs protect; diaphragm is the muscle under the lungs."], ["Q4", "The cartilage keeps the trachea open so it does not collapse [1] when the air pressure inside falls as we breathe in, so air can always flow [1]."]], "3": [["Q5", "Breathing moves air; gas exchange is diffusion across the alveolus wall; respiration is the reaction in cells."], ["Q6", "Breathing is the movement of air into and out of the lungs [1]; respiration is a chemical reaction in cells that releases energy from glucose [1]."]], "4": [["Q7", "Air is breathed into the alveoli of the lungs [1]; oxygen diffuses into the blood in the capillaries [1]; the heart pumps the blood through arteries to the leg muscle [1]."]], "5": [["Q8", "At altitude each breath holds less oxygen [1]; the body responds by making more red blood cells with haemoglobin, so it can carry more oxygen [1]; is it fair that athletes born at altitude have an advantage, or that others use altitude tents [1]."]], "6": [["Exit ticket", "Nasal cavity, trachea, bronchus, bronchiole, alveolus."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q4", "q3_1": "Q6", "q4_0": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "20fcf22e-4e2a-5878-a506-a5ef26c772b7", "ext": "G9-BIO-BODY-L2", "title": "Biology · Body systems · Lesson 2: Gas exchange in the alveoli: form and function", "summary": "MYP 4 · Biology · Body systems", "url": "/g9-bio-body-2/", "max": 21, "sort": 12, "msort": 88, "csort": 15, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 2, "n": 2, "ans": ["Into the blood", "Out of the blood"], "tip": "Gases diffuse from high to low concentration."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 2, "pts": [["high", "higher", "more oxygen"], ["low", "lower", "less oxygen"]], "tips": ["Compare the oxygen concentration on each side."]}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 2, "pts": [["carries oxygen away", "removes oxygen", "takes oxygen away", "new blood", "fresh blood", "brings carbon dioxide"], ["gradient", "concentration difference", "steep", "low oxygen"]], "tips": ["What happens to the oxygen once it enters the blood?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 5, "n": 5, "ans": ["Large surface area", "Walls one cell thick", "Rich capillary network", "Moist lining", "Ventilation"], "tip": "Each feature makes diffusion faster in a different way."}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 4, "pts": [["surface area", "many alveoli", "large area"], ["more", "faster", "more gas", "more oxygen", "at once"], ["thin", "one cell", "short distance", "capillar", "blood supply", "moist"], ["short distance", "distance is short", "fast", "gradient", "dissolve", "quick"]], "tips": ["Name a feature, then say what it does; then a second one."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q7", "max": 3, "pts": [["surface area", "less area", "smaller area"], ["less oxygen", "less gas", "slower diffusion", "less diffusion"], ["blood", "breathe faster", "breathless", "cells", "respiration"]], "tips": ["Fewer, larger sacs: what happens to the area?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 3, "pts": [["24"], ["3 : 1", "3:1", "24/8", "24 ÷ 8", "= 3", "ratio of 3", "ratio is 3", "3 to 1"], ["smaller", "decreases", "falls", "goes down", "less"]], "tips": ["Area = 6 × side × side. Volume = side × side × side."]}]}, "models": {"1": [["Q1", "Many tiny sacs have a much larger total surface area than one big sac, so more oxygen can diffuse into the blood at the same time."], ["Q2", "Oxygen is high in the alveolus and low in the blood, so it moves in; carbon dioxide is high in the blood, so it moves out."]], "2": [["Q3", "The air in the alveolus has a higher concentration of oxygen [1] than the blood arriving in the capillary, which has a lower concentration, so oxygen moves down the concentration gradient [1]."], ["Q4", "The moving blood carries oxygen away and brings new blood [1], so the oxygen concentration in the blood stays low and the concentration gradient stays steep [1]."]], "3": [["Q5", "Area: more gas at once. Thin walls: short distance. Capillaries and ventilation: steep gradient. Moisture: gases dissolve."], ["Q6", "The alveoli have a very large surface area [1], so more oxygen can diffuse into the blood at the same time [1]; their walls are only one cell thick [1], so the diffusion distance is short and diffusion is fast [1]."]], "4": [["Q7", "The total surface area of the alveoli is reduced [1]; so less oxygen diffuses into the blood [1]; the cells get less oxygen for respiration, so the person breathes faster and feels breathless [1]."]], "5": [["Q8", "Surface area = 6 × 2 × 2 = 24 cm² [1]; volume = 8 cm³, so the ratio is 24 ÷ 8 = 3 : 1 [1]; as an organism gets bigger the ratio decreases, so it needs special surfaces such as lungs [1]."]], "6": [["Exit ticket", "A large surface area, walls one cell thick, a rich capillary network (also a moist lining and ventilation)."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q3", "q2_1": "Q4", "q3_1": "Q6", "q4_0": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "654fc811-4df9-5bd9-b9cd-c1e84f036f18", "ext": "G9-BIO-BODY-L3", "title": "Biology · Body systems · Lesson 3: Ventilation: the muscles of breathing in and out", "summary": "MYP 4 · Biology · Body systems", "url": "/g9-bio-body-3/", "max": 26, "sort": 13, "msort": 89, "csort": 16, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 4, "n": 4, "ans": ["Moves up / out", "Moves down / in", "Moves down / in", "Moves up / out"], "tip": "Feel it with your hands."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 6, "n": 6, "ans": ["Inhalation", "Exhalation", "Inhalation", "Exhalation", "Inhalation", "Exhalation"], "tip": "Think volume first, then pressure."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 4, "pts": [["diaphragm contracts", "diaphragm flattens", "diaphragm moves down"], ["intercostal", "ribs up", "ribs move up", "ribs out"], ["volume increases", "volume of the thorax increases", "larger volume", "volume of the chest increases", "volume goes up"], ["pressure decreases", "pressure falls", "lower pressure", "pressure drops", "air rushes in", "air flows in", "air moves in"]], "tips": ["Muscles → ribs and diaphragm → volume → pressure → air."]}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["forced", "extra force", "push harder", "more force", "higher pressure"], ["ribs down", "pull the ribs down", "decrease volume", "reduce the volume", "smaller volume"]], "tips": ["Normal breathing out is passive. Is this normal?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 4, "n": 4, "ans": ["Lungs", "Trachea and bronchi", "Diaphragm", "Chest wall and ribs"], "tip": "Match the model to the body."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 3, "pts": [["shows", "volume", "pressure", "air flows", "balloons inflate", "diaphragm"], ["rigid", "ribs", "does not move", "cannot move", "glass", "intercostal"], ["sheet", "pulled down", "dome", "balloon", "alveoli", "one cell", "no muscle", "pleural", "not like"]], "tips": ["What does it show well? What can it not show?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 3, "pts": [["15"], ["increase", "faster", "higher", "goes up", "rises"], ["oxygen", "carbon dioxide", "respiration", "energy", "muscles"]], "tips": ["Breaths in 20 s × 3 = breaths in 60 s."]}]}, "models": {"1": [["Q1", "The ribs move up and out when breathing in, then down and in. Under the lungs the diaphragm moves down (flattens) when breathing in and moves up when breathing out."], ["Q2", "Breathing in: ribs up and out, diaphragm down. Breathing out: ribs down and in, diaphragm up."]], "2": [["Q3", "Inhalation: diaphragm contracts, ribs up and out, volume up, pressure down. Exhalation: muscles relax, volume down, pressure up, air out."]], "3": [["Q4", "The diaphragm contracts and flattens [1]; the external intercostal muscles contract and pull the ribs up and out [1]; the volume of the thorax increases [1]; the pressure in the lungs decreases so air flows in [1]."], ["Q5", "Blowing up a balloon needs a forced exhalation with a higher pressure [1]; the internal intercostal muscles contract to pull the ribs down and in, decreasing the volume of the chest more [1]."]], "4": [["Q6", "Balloons: lungs. Y-tube: trachea and bronchi. Rubber sheet: diaphragm. Jar: chest wall."], ["Q7", "It shows that increasing the volume lowers the pressure and makes the balloons fill [1]; but the jar is rigid, so it cannot show the ribs moving or the intercostal muscles [1]; and the rubber sheet is pulled by hand, unlike the dome-shaped diaphragm that contracts, and the balloons are not like alveoli [1]."]], "5": [["Q8", "Rate = 5 × 3 = 15 breaths per minute [1]; during the run the breathing rate would increase [1] because the muscles respire faster, so more oxygen must be taken in and more carbon dioxide removed [1]."]], "6": [["Exit ticket", "The volume increases and the pressure decreases, so air flows into the lungs."]]}, "labels": {"q1_0": "Q1", "q3_0": "Q4", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "90a6debd-069c-5110-b8df-e0d1ac93970f", "ext": "G9-BIO-BODY-L4", "title": "Biology · Body systems · Lesson 4: Inhaled and exhaled air: evidence of respiration", "summary": "MYP 4 · Biology · Body systems", "url": "/g9-bio-body-4/", "max": 20, "sort": 14, "msort": 90, "csort": 17, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 5, "n": 5, "ans": ["Higher in inhaled air", "Higher in exhaled air", "About the same", "Higher in exhaled air", "Higher in exhaled air"], "tip": "Which gas is used and which are made?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 2, "pts": [["diffuses into the blood", "into the blood", "absorbed", "enters the blood"], ["respiration", "used by cells", "used in cells", "cells use"]], "tips": ["Where does the oxygen go?"]}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 1, "pts": [["not used", "not needed", "does not use", "doesn't use", "not absorbed"]], "tips": ["Does the body use nitrogen gas?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 4, "n": 4, "ans": ["Independent variable", "Dependent variable", "Control variable", "Control variable"], "tip": "What do you change, measure and keep the same?"}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 2, "pts": [["exhaled", "breathed out"], ["respiration", "more carbon dioxide", "cells make", "produced", "produce carbon dioxide"]], "tips": ["If… then… because…"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q7", "max": 3, "pts": [["100"], ["5", "21 - 16", "21 − 16"], ["24", "0.24", "5/21", "5 ÷ 21", "about a quarter", "quarter"]], "tips": ["Divide 4 by 0.04. Then (21 − 16) ÷ 21."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 3, "pts": [["diffus", "alveol", "lungs", "from the blood"], ["quick", "fast", "no needle", "roadside", "easy", "cheap", "painless"], ["not exact", "less accurate", "estimate", "calibrat", "mouthwash", "error", "blood test", "confirm"]], "tips": ["Think about where gases cross between the blood and the air."]}]}, "models": {"1": [["Q1", "The mirror mists up with tiny water droplets. Exhaled air contains more water vapour than inhaled air, and it is warm."], ["Q2", "Oxygen is used, so it is lower in exhaled air; carbon dioxide and water are made, so they are higher; nitrogen is not used."]], "2": [["Q3", "Some oxygen diffuses from the alveoli into the blood [1] and is carried to the cells, where it is used in respiration [1]."], ["Q4", "The body does not use nitrogen gas, so it is breathed out unchanged [1]."]], "3": [["Q5", "Independent: type of air. Dependent: milkiness or time. Control: volume of limewater and amount of air."], ["Q6", "If exhaled air bubbles through limewater, it will turn milky faster than with inhaled air [1], because exhaled air contains more carbon dioxide produced by respiration in the cells [1]."]], "4": [["Q7", "Carbon dioxide: 4 ÷ 0.04 = 100 times more [1]; oxygen absorbed = 21 − 16 = 5% of the air [1]; 5 ÷ 21 = about 0.24, so about a quarter (24%) of the oxygen is absorbed [1]."]], "5": [["Q8", "Alcohol diffuses from the blood in the lung capillaries into the alveoli and is breathed out [1]; an advantage is that the test is quick and painless at the roadside [1]; a limitation is that it is less accurate than a blood test (affected by mouthwash or calibration), so a blood test may be needed to confirm [1]."]], "6": [["Exit ticket", "Exhaled air has less oxygen and more carbon dioxide; carbon dioxide is higher because respiration in cells produces it."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q3", "q2_1": "Q4", "q3_1": "Q6", "q4_0": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "4ccbde20-116d-5984-92bd-7f0dffb4f91e", "ext": "G9-BIO-BODY-L5", "title": "Biology · Body systems · Lesson 5: Lung volumes, exercise and fitness", "summary": "MYP 4 · Biology · Body systems", "url": "/g9-bio-body-5/", "max": 26, "sort": 15, "msort": 91, "csort": 18, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 3, "n": 3, "ans": ["Tidal volume", "Vital capacity", "Residual volume"], "tip": "Normal, maximum or left over?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 2, "pts": [["0.5 × 15", "0.5 x 15", "0.5*15"], ["7.5"]], "tips": ["Tidal volume × breathing rate."]}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 3, "pts": [["2.0 × 30", "2 × 30", "2 x 30", "2.0 x 30"], ["60"], ["8"]], "tips": ["Multiply, then divide by 7.5."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q5", "max": 3, "pts": [["respir", "muscles"], ["more oxygen", "oxygen"], ["carbon dioxide", "remove", "get rid"]], "tips": ["Muscles → respiration → gases."]}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 2, "pts": [["oxygen debt", "lactic acid", "anaerobic"], ["break down", "remove", "oxygen is used", "repay", "get rid"]], "tips": ["What did the muscles make when oxygen ran short?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q7", "max": 6, "n": 6, "ans": ["Increase", "Decrease", "Increase", "Decrease", "Increase", "Decrease"], "tip": "Does it strengthen or damage the system?"}, {"kind": "text", "id": "q4_1", "q": "Q8", "max": 2, "pts": [["larger tidal", "deeper", "bigger breath", "vital capacity", "stronger muscles", "stronger diaphragm"], ["same oxygen", "enough oxygen", "fewer breaths", "efficient"]], "tips": ["If each breath is bigger…"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q9", "max": 5, "pts": [["time", "minutes", "duration"], ["breathing rate", "breaths per minute", "count breaths"], ["same person", "same speed", "same rope", "same rate", "rest", "resting rate", "same intensity"], ["repeat", "three times", "mean", "average", "more people"], ["safe", "asthma", "stop if", "dizzy", "inhaler", "space", "clear area", "shoes", "water"]], "tips": ["Change, measure, keep the same, repeat, be safe."]}]}, "models": {"1": [["Q1", "The deep breath moves many times more air (about 4 dm³ compared with 0.5 dm³). The lungs never empty because some air (residual volume) stays in them to keep the alveoli open."], ["Q2", "Normal breath: tidal volume. Maximum: vital capacity. Left over: residual volume."]], "2": [["Q3", "Minute volume = 0.5 × 15 [1] = 7.5 dm³ per minute [1]."], ["Q4", "Volume per minute = 2.0 × 30 [1] = 60 dm³ per minute [1]; 60 ÷ 7.5 = 8 times larger [1]."]], "3": [["Q5", "The muscles contract more, so they respire faster to release more energy [1]; they need more oxygen to be taken in [1]; and more carbon dioxide is produced, which must be removed [1]."], ["Q6", "During the race the muscles respired anaerobically and made lactic acid (an oxygen debt) [1]; extra oxygen is needed afterwards to break down the lactic acid [1]."]], "4": [["Q7", "Training, growth and wind instruments increase it; smoking, age and pollution decrease it."], ["Q8", "Training strengthens the diaphragm and intercostal muscles, so each breath is deeper (larger tidal volume) [1]; the same amount of oxygen is taken in with fewer breaths, which is more efficient [1]."]], "5": [["Q9", "Independent variable: time skipping (e.g. 1, 2, 3, 4 and 5 minutes) [1]; dependent variable: breathing rate, counted in breaths per minute straight after skipping [1]; control: the same person skipping at the same speed, resting until the breathing rate returns to normal between trials [1]; repeat each time three times and calculate a mean [1]; safety: stop if dizzy, and anyone with asthma keeps an inhaler nearby [1]."]], "6": [["Exit ticket", "The largest volume of air that can be breathed out after the deepest breath in; regular aerobic training (or swimming, singing, being taller) increases it."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q3", "q2_1": "Q4", "q3_0": "Q5", "q3_1": "Q6", "q4_1": "Q8", "q5_0": "Q9", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "6002225a-a5cf-5404-97ee-a187aaeaffc9", "ext": "G9-BIO-BODY-L6", "title": "Biology · Body systems · Lesson 6: Keeping the lungs healthy: defences, smoking and disease", "summary": "MYP 4 · Biology · Body systems", "url": "/g9-bio-body-6/", "max": 26, "sort": 16, "msort": 92, "csort": 19, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 4, "n": 4, "ans": ["Mucus", "Cilia", "Nose hairs", "Coughing"], "tip": "Trap, sweep, filter or blast?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Nicotine", "Tar", "Carbon monoxide", "Tar"], "tip": "Addiction, cancer or oxygen?"}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 3, "pts": [["tar", "smoke"], ["cilia", "stop", "paralys", "damage"], ["mucus", "bacteria", "microbes", "pathogens", "not removed", "stays", "build up"]], "tips": ["Smoke → cilia → mucus → microbes."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 5, "n": 5, "ans": ["Emphysema", "Asthma", "Lung cancer", "Chronic bronchitis", "Asthma"], "tip": "Alveoli, airways, cells or bronchi?"}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 3, "pts": [["narrow", "constrict", "contract"], ["less air", "harder", "resistance", "air cannot", "wheez", "less oxygen"], ["relax", "open", "widen", "dilat"]], "tips": ["What happens to the bronchioles?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q7", "max": 4, "pts": [["more cigarettes", "increases", "higher", "rises", "the more"], ["25"], ["other factor", "another factor", "other cause", "pollution", "job", "not prove", "coincidence", "other variable"], ["experiment", "carcinogen", "tar", "mechanism", "mutation", "laboratory"]], "tips": ["The more…, the more… Then divide 251 by 10."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 3, "pts": [["cookstove", "ban", "tax", "emission", "ventilat", "gas cooker", "lpg", "electric", "public transport", "trees", "education", "campaign"], ["less smoke", "fewer", "reduce", "cleaner", "benefit", "healthier"], ["cost", "expensive", "afford", "enforce", "difficult", "jobs", "habit", "not everyone"]], "tips": ["Benefit, difficulty, opinion."]}]}, "models": {"1": [["Q1", "Coughing pushes out mucus and irritants. Smoke and infections make the airways produce more mucus, and smoke stops the cilia working, so the mucus has to be coughed out."], ["Q2", "Mucus traps; cilia sweep; nose hairs filter; coughing clears."]], "2": [["Q3", "Nicotine: addiction. Tar: cancer and stops cilia. Carbon monoxide: less oxygen carried."], ["Q4", "Tar in the smoke [1] stops the cilia beating / damages them [1], so mucus with trapped bacteria is not removed and builds up in the lungs, causing infections [1]."]], "3": [["Q5", "Emphysema: alveoli. Asthma: narrow airways, inhaler. Cancer: tumour. Bronchitis: mucus and cough."], ["Q6", "The muscle around the bronchioles contracts and the lining is inflamed, so the airways narrow [1]; less air can flow through, so less oxygen reaches the alveoli and the person wheezes [1]; the inhaler contains a drug that relaxes the muscle and widens the airways [1]."]], "4": [["Q7", "The more cigarettes smoked per day, the higher the death rate from lung cancer [1]; 251 ÷ 10 = about 25 times greater [1]; a correlation could be caused by another factor such as air pollution at work [1]; so scientists also need laboratory evidence that carcinogens in tar cause mutations [1]."]], "5": [["Q8", "Using clean cookstoves or LPG gas instead of charcoal indoors [1] means families breathe in less smoke, so fewer children get chest infections and asthma [1]; but the stoves and gas cost money that poor families may not afford, so I think the government should subsidise them because the health costs saved are larger [1]."]], "6": [["Exit ticket", "Tar stops the cilia beating, so mucus containing bacteria is not swept out and the bacteria cause infections."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q4", "q3_1": "Q6", "q4_0": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "4e91b920-b8e9-5303-8ebc-5805c57b8ca9", "ext": "G9-BIO-BODY-L7", "title": "Biology · Body systems · Lesson 7: Stimulus and response: receptors, the CNS and effectors", "summary": "MYP 4 · Biology · Body systems", "url": "/g9-bio-body-7/", "max": 34, "sort": 17, "msort": 93, "csort": 20, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 6, "n": 6, "ans": ["Stimulus", "Receptor", "Effector", "Response", "Stimulus", "Effector"], "tip": "Change, detector, doer, action."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 6, "n": 6, "ans": ["Ear", "Skin", "Nose", "Eye", "Tongue", "Ear"], "tip": "Which receptor is sensitive to this energy or chemical?"}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 2, "pts": [["detect", "sense"], ["impulse", "electrical", "signal", "message"]], "tips": ["Detect, then convert."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 6, "n": 6, "ans": ["4th", "1st", "6th", "2nd", "3rd", "5th"], "tip": "Start with the stimulus, end with the response."}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 2, "pts": [["brain", "spinal cord"], ["coordinat", "process", "decide", "receive", "interpret", "sends impulses"]], "tips": ["What is in it, and what does it do?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q7", "max": 6, "n": 6, "ans": ["Nervous system", "Hormonal system", "Nervous system", "Hormonal system", "Hormonal system", "Nervous system"], "tip": "Electrical or chemical? Fast or slow?"}, {"kind": "text", "id": "q4_1", "q": "Q8", "max": 3, "pts": [["electrical", "impulse"], ["blood", "chemical", "hormone"], ["faster", "slower", "longer", "shorter", "specific", "many organs", "widespread", "target"]], "tips": ["Messages, transport, speed, duration."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q9", "max": 3, "pts": [["impulse", "messages", "signals"], ["brain", "cannot reach", "can't reach", "not reach", "muscles", "legs"], ["wheelchair", "ramp", "physiotherapy", "exoskeleton", "implant", "access", "stem cell", "support", "rehabilitation"]], "tips": ["The spinal cord is the link between the brain and the body."]}]}, "models": {"1": [["Q1", "Heat (stimulus) was detected by receptors in the skin; impulses travelled along nerves to the spinal cord and back to the arm muscles (effectors), which contracted to pull the hand away (response)."], ["Q2", "Stimulus: the change. Receptor: detects it. Effector: muscle or gland. Response: what happens."]], "2": [["Q3", "Sound and balance: ear. Heat: skin. Smell: nose. Light and colour: eye. Taste: tongue."], ["Q4", "A receptor detects a stimulus [1] and converts it into electrical impulses that travel along neurons [1]."]], "3": [["Q5", "Ball moves → retina detects → sensory nerve → brain decides → motor neurons → muscles contract."], ["Q6", "The CNS is the brain and the spinal cord [1]; it receives impulses from receptors, processes the information and sends impulses to effectors (it coordinates the response) [1]."]], "4": [["Q7", "Electrical, fast, short: nervous. Chemical in blood, slower, longer: hormonal."], ["Q8", "The nervous system uses electrical impulses along neurons [1], while the hormonal system uses chemical hormones carried in the blood [1]; nervous responses are faster and shorter-lasting, while hormonal responses are slower and last longer [1]."]], "5": [["Q9", "Impulses travel through the spinal cord between the brain and the body [1]; after the injury, impulses from the brain cannot reach the motor neurons of the leg muscles, so the legs cannot be moved [1]; wheelchairs, ramps and accessible buildings, physiotherapy or new exoskeleton technology can help them live independently [1]."]], "6": [["Exit ticket", "Stimulus → receptor → sensory neuron → CNS → motor neuron → effector → response."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q4", "q3_1": "Q6", "q4_1": "Q8", "q5_0": "Q9", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "f35b14bd-fcc3-50a0-b0cc-93e3696c90ce", "ext": "G9-BIO-BODY-L8", "title": "Biology · Body systems · Lesson 8: Neurons, impulses and synapses", "summary": "MYP 4 · Biology · Body systems", "url": "/g9-bio-body-8/", "max": 31, "sort": 18, "msort": 94, "csort": 21, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 5, "n": 5, "ans": ["Cell body", "Dendrite", "Axon", "Myelin sheath", "Nerve ending"], "tip": "Follow the impulse through the cell."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 6, "n": 6, "ans": ["Sensory neuron", "Relay neuron", "Motor neuron", "Relay neuron", "Motor neuron", "Sensory neuron"], "tip": "Where does it start and where does it end?"}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 2, "pts": [["cell body"], ["middle", "outside", "ganglion", "end", "in the cns", "spinal cord", "along the fibre"]], "tips": ["Look at where the cell body is."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 5, "n": 5, "ans": ["4th", "1st", "3rd", "5th", "2nd"], "tip": "Electrical → chemical → electrical."}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 4, "pts": [["arrives", "reaches the end"], ["neurotransmitter", "chemical", "released"], ["diffuses", "across the gap"], ["bind", "receptor", "new impulse", "next neuron"]], "tips": ["Four steps."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q7", "max": 4, "pts": [["long", "axon"], ["far", "distance", "from the spinal cord", "to the foot", "reach"], ["myelin", "fatty", "insulat"], ["faster", "quick", "speed"]], "tips": ["Feature → how it helps; twice."]}, {"kind": "text", "id": "q4_1", "q": "Q8", "max": 2, "pts": [["released", "only one side", "vesicles", "first neuron", "end of the axon"], ["receptor", "only on the next", "other side", "second neuron"]], "tips": ["Where is the neurotransmitter made, and where are the receptors?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q9", "max": 3, "pts": [["slower", "more slowly", "longer", "reaction time", "delay"], ["brake", "crash", "hazard", "stopping distance", "further"], ["breathalyser", "enforce", "fine", "safer", "protect", "police", "lives"]], "tips": ["Synapse → reaction time → accident → law."]}]}, "models": {"1": [["Q1", "A neuron is very long with a long axon and many branches (dendrites). It is long to carry impulses over long distances and branched to connect with many other cells."], ["Q2", "Cell body: nucleus. Dendrites: receive. Axon: carries. Myelin: insulates and speeds up. Nerve endings: pass on."]], "2": [["Q3", "Sensory: from receptors. Relay: in the CNS. Motor: to effectors."], ["Q4", "The cell body is in a different place [1]: in a motor neuron it is at one end, inside the CNS, but in a sensory neuron it is partway along the fibre, just outside the spinal cord (in a ganglion) [1]."]], "3": [["Q5", "Arrives → released → diffuses → binds → new impulse."], ["Q6", "The impulse arrives at the end of the first neuron [1]; a neurotransmitter is released into the gap [1]; it diffuses across the gap [1]; it binds to receptors on the next neuron and starts a new impulse [1]."]], "4": [["Q7", "It has a very long axon [1], so a single cell reaches all the way from the spinal cord to the foot [1]; the axon is covered in a myelin sheath [1] that insulates it and makes the impulse travel faster [1]."], ["Q8", "Neurotransmitter is only released from the end of the first neuron [1]; the receptors that it binds to are only on the next neuron [1]."]], "5": [["Q9", "Impulses cross synapses more slowly, so the driver's reaction time is longer [1]; the car travels further before the driver brakes for a hazard, so accidents are more likely [1]; a legal limit tested with breathalysers protects other road users, although it only works if police enforce it [1]."]], "6": [["Exit ticket", "Sensory: receptor to CNS; relay: within the CNS; motor: CNS to effector."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q4", "q3_1": "Q6", "q4_0": "Q7", "q4_1": "Q8", "q5_0": "Q9", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "ae4457dc-8015-5733-98f7-0cb425845e36", "ext": "G9-BIO-BODY-L9", "title": "Biology · Body systems · Lesson 9: Reflex actions and reaction time", "summary": "MYP 4 · Biology · Body systems", "url": "/g9-bio-body-9/", "max": 30, "sort": 19, "msort": 95, "csort": 22, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 6, "n": 6, "ans": ["Reflex", "Voluntary action", "Reflex", "Voluntary action", "Reflex", "Reflex"], "tip": "Did you think about it first?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 6, "n": 6, "ans": ["4th", "1st", "5th", "2nd", "6th", "3rd"], "tip": "Receptor first, effector last."}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 4, "pts": [["receptor", "pain receptor", "skin"], ["sensory neuron", "sensory"], ["relay", "spinal cord"], ["motor neuron", "muscle", "effector"]], "tips": ["Receptor, three neurons, effector."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q5", "max": 2, "pts": [["spinal cord", "not the brain", "does not go to the brain", "no thinking", "without the brain", "bypass"], ["short", "fewer synapses", "fewer neurons", "less", "no decision"]], "tips": ["What part of the CNS does it use?"]}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 2, "pts": [["protect", "harm", "damage", "injury", "danger"], ["fast", "quick", "automatic", "without thinking", "before"]], "tips": ["What would happen if you had to think first?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q7", "max": 3, "pts": [["17"], ["0.17", "0.18"], ["same hand", "same person drops", "no warning", "repeat", "more trials", "distraction", "same position", "practice", "more students"]], "tips": ["Add the five results and divide by five."]}, {"kind": "choice", "id": "q4_1", "q": "Q8", "max": 4, "n": 4, "ans": ["Independent variable", "Dependent variable", "Control variable", "Control variable"], "tip": "Change, measure, keep the same."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q9", "max": 3, "pts": [["damage", "injur", "not working", "problem"], ["nerve", "brain", "neuron", "reflex arc", "pathway"], ["quick", "simple", "cheap", "unconscious", "no equipment", "early", "evidence"]], "tips": ["If the reflex arc is broken…"]}]}, "models": {"1": [["Q1", "The lower leg kicks forward automatically (the knee-jerk reflex). You did not decide to move it: it is involuntary."], ["Q2", "Blinking, pulling away, pupil changes and coughing are reflexes. Writing and kicking a ball are voluntary."]], "2": [["Q3", "Heat → receptors → sensory neuron → relay neuron → motor neuron → muscle."], ["Q4", "Pain receptors in the skin detect the thorn [1]; a sensory neuron carries the impulse to the spinal cord [1]; a relay neuron in the spinal cord passes it on [1]; a motor neuron carries it to the arm muscle, which contracts and pulls the hand away [1]."]], "3": [["Q5", "The impulse passes through the spinal cord and does not need the brain to decide [1]; the pathway is short with only a few synapses, so it takes less time [1]."], ["Q6", "Reflexes protect the body from harm such as burns or damage to the eyes [1], because they happen very fast and automatically, before there is time to think [1]."]], "4": [["Q7", "Mean = (18 + 15 + 21 + 15 + 16) ÷ 5 = 85 ÷ 5 = 17 cm [1]; this is a reaction time of about 0.17 s [1]; to improve it, use the same hand and the same person dropping without warning, and do more trials [1]."], ["Q8", "Independent: caffeine or not. Dependent: distance fallen. Controls: same hand, ruler and position."]], "5": [["Q9", "It suggests damage [1] to the nerves or the part of the brain in the pupil reflex arc [1]; reflex tests are quick, simple and work even on an unconscious patient, so they give early evidence of brain injury [1]."]], "6": [["Exit ticket", "Sensory neuron, relay neuron, motor neuron."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q4", "q3_0": "Q5", "q3_1": "Q6", "q4_0": "Q7", "q5_0": "Q9", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "f5560d2c-7884-5b6e-921d-6021d1d6f372", "ext": "G9-BIO-BODY-L10", "title": "Biology · Body systems · Lesson 10: The skeleton: functions and bone", "summary": "MYP 4 · Biology · Body systems", "url": "/g9-bio-body-10/", "max": 27, "sort": 20, "msort": 96, "csort": 23, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 6, "n": 6, "ans": ["Protection", "Making blood cells", "Movement", "Support", "Storing minerals", "Protection"], "tip": "Think about what each bone does."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 6, "n": 6, "ans": ["Femur", "Humerus", "Patella", "Tibia", "Sternum", "Pelvis"], "tip": "Use the skeleton diagram."}, {"kind": "choice", "id": "q2_1", "q": "Q4", "max": 3, "n": 3, "ans": ["Brain", "Heart and lungs", "Spinal cord"], "tip": "What is inside each?"}], "3": [{"kind": "text", "id": "q3_0", "q": "Q5", "max": 2, "pts": [["cells", "blood vessel", "nerves", "blood supply"], ["grow", "repair", "heal", "stronger", "marrow", "blood cells"]], "tips": ["What can bone do that a stone cannot?"]}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 2, "pts": [["calcium", "phosphate", "mineral"], ["collagen", "protein", "fibres"]], "tips": ["Two materials, two properties."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q7", "max": 4, "pts": [["muscular", "muscle", "respiratory", "circulatory", "nervous"], ["move", "blood cells", "marrow", "ribs", "breathing", "protect", "brain", "spinal cord", "lever"], ["muscular", "muscle", "respiratory", "circulatory", "nervous", "blood"], ["move", "blood cells", "marrow", "ribs", "breathing", "protect", "brain", "spinal cord", "lever", "oxygen"]], "tips": ["Name the system, then how they work together; twice."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 4, "pts": [["calcium", "milk", "omena", "dairy", "green vegetables"], ["harden", "hard", "calcium phosphate", "mineral", "build bone", "strong"], ["exercise", "running", "jumping", "sport", "weight", "sunlight", "vitamin d"], ["denser", "stronger", "absorb calcium", "more bone", "density"]], "tips": ["What goes into bone? What makes it denser?"]}]}, "models": {"1": [["Q1", "You could not stand up or keep your shape; the brain, heart and lungs would not be protected; muscles would have nothing to pull on, so you could not move; you would also not make blood cells in bone marrow."], ["Q2", "Skull and ribs: protection. Marrow: blood cells. Muscles and joints: movement. Spine: support. Calcium: minerals."]], "2": [["Q3", "Femur: thigh. Humerus: upper arm. Patella: kneecap. Tibia: shin. Sternum: breastbone. Pelvis: hips."], ["Q4", "Skull: brain. Ribs: heart and lungs. Vertebrae: spinal cord."]], "3": [["Q5", "Bone contains living cells supplied by blood vessels and nerves [1]; it can grow, repair itself after a fracture and become stronger with exercise [1]."], ["Q6", "Calcium phosphate minerals make bone hard [1]; collagen protein fibres make it slightly flexible so it does not snap easily [1]."]], "4": [["Q7", "With the muscular system [1]: muscles pull on bones at joints so the body moves [1]; with the circulatory system [1]: red bone marrow makes the red blood cells that carry oxygen in the blood [1]."]], "5": [["Q8", "Eat calcium-rich foods such as milk, omena (small fish) and green vegetables [1], because calcium is used to make the calcium phosphate that hardens bone [1]; do weight-bearing exercise such as running and jumping [1], because the stress makes bone cells build denser, stronger bone [1]."]], "6": [["Exit ticket", "Support, protection of organs and movement (also making blood cells and storing calcium)."]]}, "labels": {"q1_0": "Q1", "q3_0": "Q5", "q3_1": "Q6", "q4_0": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "0281d655-6ef9-5a6b-a9b8-b1d79cbbd2b4", "ext": "G9-BIO-BODY-L11", "title": "Biology · Body systems · Lesson 11: Types of joints", "summary": "MYP 4 · Biology · Body systems", "url": "/g9-bio-body-11/", "max": 29, "sort": 21, "msort": 97, "csort": 24, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 5, "n": 5, "ans": ["Fixed", "Slightly movable", "Freely movable", "Freely movable", "Slightly movable"], "tip": "How much does it move?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 6, "n": 6, "ans": ["Hinge", "Ball and socket", "Pivot", "Gliding", "Hinge", "Ball and socket"], "tip": "One plane, all directions, turning or sliding?"}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 4, "pts": [["hinge", "one plane", "one direction", "bend"], ["elbow", "knee", "finger"], ["all directions", "many directions", "rotat", "circle"], ["shoulder", "hip"]], "tips": ["Movement + example, twice."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q5", "max": 2, "pts": [["shoulder is more", "shoulder will", "shoulder dislocates", "shoulder joint is more"], ["less tightly", "less stable", "moves more", "pops out", "not held", "loose"]], "tips": ["Deep cups hold balls tightly."]}, {"kind": "choice", "id": "q3_1", "q": "Q6", "max": 4, "n": 4, "ans": ["Flexion", "Extension", "Rotation", "Flexion"], "tip": "Bending, straightening or turning?"}], "4": [{"kind": "text", "id": "q4_0", "q": "Q7", "max": 4, "pts": [["hip"], ["ball and socket", "ball-and-socket"], ["knee"], ["hinge", "extension", "straighten", "flexion", "bend"]], "tips": ["Hip, then knee."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 4, "pts": [["strong", "hard", "not break", "durable"], ["smooth", "low friction", "not rust", "not corrode", "not toxic", "not rejected", "light", "biocompatible"], ["pain", "walk", "move", "mobility", "independent", "quality of life"], ["infection", "cost", "expensive", "rejection", "wear", "loosen", "blood clot", "anaesthetic"]], "tips": ["Material properties, then benefit and risk."]}]}, "models": {"1": [["Q1", "The shoulder moves in the most directions (it is a ball-and-socket joint). The elbow moves in only one plane, bending and straightening (a hinge joint)."], ["Q2", "Skull sutures: fixed. Vertebrae and rib-sternum joints: slightly movable. Knee and shoulder: freely movable."]], "2": [["Q3", "Elbow and knee: hinge. Hip and shoulder: ball and socket. Neck: pivot. Wrist bones: gliding."], ["Q4", "A hinge joint moves in one plane only, bending and straightening [1], e.g. the elbow [1]; a ball-and-socket joint moves in all directions and can rotate [1], e.g. the shoulder [1]."]], "3": [["Q5", "The shoulder is more likely to dislocate [1], because its shallow socket holds the ball less tightly, so it moves more but is less stable [1]."], ["Q6", "Bending: flexion. Straightening: extension. Turning: rotation."]], "4": [["Q7", "The hip [1], a ball-and-socket joint, swings the leg forward [1]; the knee [1], a hinge joint, straightens (extension) to strike the ball [1]."]], "5": [["Q8", "The material must be strong so it does not break [1] and smooth and non-corroding so it moves with low friction inside the body [1]; the benefit is less pain and the ability to walk again [1]; a risk is infection or the joint wearing and loosening, and the operation is expensive [1]."]], "6": [["Exit ticket", "Elbow: hinge, bending and straightening in one plane; shoulder: ball-and-socket, movement in all directions."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q4", "q3_0": "Q5", "q4_0": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "7856f492-e19f-5c72-88ca-ef5b7b5241e9", "ext": "G9-BIO-BODY-L12", "title": "Biology · Body systems · Lesson 12: Synovial joints, tendons and ligaments", "summary": "MYP 4 · Biology · Body systems", "url": "/g9-bio-body-12/", "max": 23, "sort": 22, "msort": 98, "csort": 25, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 5, "n": 5, "ans": ["Cartilage", "Synovial fluid", "Synovial membrane", "Ligament", "Joint capsule"], "tip": "Smooth, oily, lining, strap or bag?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 2, "pts": [["smooth", "slippery", "slide", "without rubbing"], ["lubricat", "oil"]], "tips": ["Two parts, one job: less friction."]}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 2, "pts": [["bone to bone", "hold", "join bones", "together"], ["dislocat", "stable", "stop", "prevent", "too far", "force"]], "tips": ["What happens if they break?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 6, "n": 6, "ans": ["Tendon", "Ligament", "Tendon", "Ligament", "Tendon", "Ligament"], "tip": "Muscle-bone or bone-bone?"}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 2, "pts": [["not stretch", "do not stretch", "don't stretch", "inelastic"], ["pull", "force", "transfer", "pass", "move the bone", "all the"]], "tips": ["Imagine pulling a bone with an elastic band."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q7", "max": 3, "pts": [["cartilage", "worn", "wears away", "thin"], ["bone rub", "bones rub", "rub", "friction", "grind"], ["pain", "inflam", "swell", "damage", "stiff", "nerves"]], "tips": ["Without the smooth layer, what touches what?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 3, "pts": [["poor blood supply", "little blood", "few blood vessels", "blood supply", "collagen", "slow"], ["warm up", "stretch", "strengthen", "shoes", "strap", "tape", "brace"], ["warm up", "stretch", "strengthen", "shoes", "strap", "tape", "brace", "surface", "technique", "training"]], "tips": ["Blood supply; then prevention."]}]}, "models": {"1": [["Q1", "Synovial fluid works like the oil, lubricating the joint; ligaments work like the screws, holding the bones together. Smooth cartilage also reduces friction."], ["Q2", "Cartilage covers bone ends; fluid lubricates; membrane makes fluid; ligaments join bones; capsule encloses."]], "2": [["Q3", "Smooth cartilage covers the bone ends so they slide over each other without rubbing [1]; synovial fluid lubricates the joint, reducing friction further [1]."], ["Q4", "Ligaments join bone to bone and hold the joint together [1]; they must be strong to stop the joint dislocating or moving too far under large forces [1]."]], "3": [["Q5", "Tendons: muscle to bone, inelastic, Achilles. Ligaments: bone to bone, slightly elastic, sprains."], ["Q6", "If tendons stretched, part of the muscle's pull would be used stretching them [1]; because they do not stretch, all the force of the contracting muscle is passed to the bone to move it [1]."]], "4": [["Q7", "The smooth cartilage that covered the bone ends is worn away [1]; the bones rub directly on each other, increasing friction [1]; this damages the bone and inflames the joint, causing pain, swelling and stiffness [1]."]], "5": [["Q8", "Ligaments have a poor blood supply, so cells and nutrients for repair arrive slowly and healing takes weeks [1]; warming up and stretching before playing [1] and wearing supportive shoes or ankle strapping (or strengthening exercises) reduce the risk [1]."]], "6": [["Exit ticket", "A tendon joins muscle to bone and does not stretch; a ligament joins bone to bone and is slightly elastic."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q3", "q2_1": "Q4", "q3_1": "Q6", "q4_0": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "4593f994-40c5-5d44-8a46-e5e604353460", "ext": "G9-BIO-BODY-L13", "title": "Biology · Body systems · Lesson 13: Muscles: types and how they work", "summary": "MYP 4 · Biology · Body systems", "url": "/g9-bio-body-13/", "max": 27, "sort": 23, "msort": 99, "csort": 26, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 4, "n": 4, "ans": ["False", "True", "False", "True"], "tip": "Muscles only pull."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 6, "n": 6, "ans": ["Cardiac", "Smooth", "Skeletal", "Smooth", "Cardiac", "Skeletal"], "tip": "Where is it and do you control it?"}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 3, "pts": [["striated", "stripe", "both contract", "both"], ["voluntary", "involuntary", "control"], ["tire", "fatigue", "heart", "bones", "branched", "location"]], "tips": ["Stripes? Control? Tiredness?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 5, "n": 5, "ans": ["5th", "1st", "2nd", "4th", "3rd"], "tip": "Nerve → muscle → tendon → bone."}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 2, "pts": [["only pull", "cannot push", "can't push", "only contract"], ["another muscle", "other muscle", "opposite", "pull it back", "return", "straighten"]], "tips": ["One pulls, then what?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q7", "max": 2, "pts": [["respiration", "respire"], ["energy", "contract", "contraction"]], "tips": ["What happens in mitochondria?"]}, {"kind": "text", "id": "q4_1", "q": "Q8", "max": 3, "pts": [["not enough oxygen", "oxygen", "cannot supply"], ["anaerobic"], ["lactic acid", "fatigue", "cramp"]], "tips": ["Oxygen → type of respiration → product."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q9", "max": 2, "pts": [["unfair", "advantage", "cheat", "fair"], ["health", "harm", "heart", "liver", "side effect", "danger", "damage"]], "tips": ["Fairness and health."]}]}, "models": {"1": [["Q1", "When the elbow bends, the front muscle (biceps) becomes shorter and harder; when the arm straightens, the back muscle (triceps) contracts and the biceps relaxes."], ["Q2", "Muscles only pull; they shorten when they contract; they are pulled back to length by another muscle; tendons join them to bones."]], "2": [["Q3", "Heart: cardiac. Gut and airways: smooth. Moving bones by choice: skeletal."], ["Q4", "Both are striated (striped) [1]; skeletal muscle is voluntary but cardiac muscle is involuntary [1]; skeletal muscle tires but cardiac muscle never fatigues (and cardiac muscle is only in the heart) [1]."]], "3": [["Q5", "Impulse → muscle contracts → pulls tendon → tendon pulls bone → bone moves at the joint."], ["Q6", "A muscle can only pull (contract), it cannot push [1]; so a second muscle is needed to pull the bone back in the opposite direction and stretch the first one again [1]."]], "4": [["Q7", "Mitochondria are where aerobic respiration happens [1]; muscles need a lot of energy to contract [1]."], ["Q8", "The heart and lungs cannot supply oxygen to the muscles fast enough [1]; the muscles respire anaerobically [1]; lactic acid builds up, causing pain and fatigue [1]."]], "5": [["Q9", "They give an unfair advantage over athletes who train without drugs [1]; and they harm the user's health, for example damaging the heart and liver [1]."]], "6": [["Exit ticket", "Skeletal (attached to bones), smooth (walls of organs such as the gut and blood vessels) and cardiac (heart)."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q4", "q3_1": "Q6", "q4_0": "Q7", "q4_1": "Q8", "q5_0": "Q9", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "e722e566-18c8-5574-815a-6c0412b74dda", "ext": "G9-BIO-BODY-L14", "title": "Biology · Body systems · Lesson 14: Antagonistic muscles and movement at the elbow", "summary": "MYP 4 · Biology · Body systems", "url": "/g9-bio-body-14/", "max": 27, "sort": 24, "msort": 100, "csort": 27, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 6, "n": 6, "ans": ["Biceps", "Triceps", "Biceps", "Triceps", "Biceps", "Triceps"], "tip": "Front muscle bends; back muscle straightens."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 3, "pts": [["biceps contracts", "biceps shortens", "biceps pulls"], ["triceps relaxes", "triceps is relaxed", "triceps lengthens", "triceps is stretched"], ["radius", "forearm", "tendon", "pulled up", "lower arm", "elbow"]], "tips": ["Which contracts, which relaxes, and what is pulled?"]}, {"kind": "choice", "id": "q2_1", "q": "Q4", "max": 4, "n": 4, "ans": ["Contracts", "Relaxes", "Contracts", "Relaxes"], "tip": "Bending: biceps. Straightening: triceps."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q5", "max": 4, "pts": [["triceps contracts", "triceps shortens", "triceps pulls"], ["tendon", "ulna"], ["biceps relaxes", "biceps is stretched", "biceps is relaxed"], ["hinge", "one plane", "pivot", "joint"]], "tips": ["Muscle → tendon → bone → joint."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 3, "n": 3, "ans": ["Pivot", "Effort", "Load"], "tip": "What turns, what pulls, what is lifted?"}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 3, "pts": [["30 × 0.30", "30 x 0.30", "9 n", "= 9", "moment of the load"], ["9 ÷ 0.04", "9/0.04", "f × 0.04", "f x 0.04", "0.04 × f"], ["225"]], "tips": ["Clockwise moment = anticlockwise moment."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 4, "pts": [["hamstrings contract", "hamstring contracts", "hamstrings shorten"], ["quadriceps relax", "quadriceps relaxes", "quads relax"], ["quadriceps contract", "quadriceps contracts", "quads contract"], ["hamstrings relax", "hamstring relaxes", "straighten", "extend"]], "tips": ["Bend first, then kick."]}]}, "models": {"1": [["Q1", "Pull the string on the front (like the biceps) to bend the arm; pull the string at the back (like the triceps) to straighten it. Pulling one lets the other go slack."], ["Q2", "Biceps: front, bends (flexor), attached to the radius. Triceps: back, straightens (extensor), attached to the ulna."]], "2": [["Q3", "The biceps contracts and shortens [1] while the triceps relaxes [1]; the biceps pulls on its tendon attached to the radius, so the forearm is raised at the elbow [1]."], ["Q4", "Lifting a cup bends the arm: biceps contracts, triceps relaxes. Pushing up straightens the arm: triceps contracts, biceps relaxes."]], "3": [["Q5", "The triceps contracts [1] and pulls on its tendon attached to the ulna [1]; the biceps relaxes and is stretched [1]; the forearm turns about the elbow, a hinge joint, so it straightens in one plane [1]."]], "4": [["Q6", "Pivot: elbow. Effort: biceps. Load: bag."], ["Q7", "Moment of the load = 30 × 0.30 = 9 N m [1]; biceps force × 0.04 = 9, so force = 9 ÷ 0.04 [1] = 225 N [1]."]], "5": [["Q8", "To bend the knee, the hamstrings contract [1] and the quadriceps relax [1]; to kick, the quadriceps contract [1] and the hamstrings relax, so the leg straightens [1]."]], "6": [["Exit ticket", "The triceps contracts and the biceps relaxes."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q3", "q3_0": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "5d583e81-f3e6-5d9c-91ff-ec04a116bdc3", "ext": "G9-BIO-BODY-L15", "title": "Biology · Body systems · Lesson 15: Movement, exercise and a healthy musculoskeletal system", "summary": "MYP 4 · Biology · Body systems", "url": "/g9-bio-body-15/", "max": 27, "sort": 25, "msort": 101, "csort": 28, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 5, "n": 5, "ans": ["Nervous system", "Muscular system", "Skeletal system", "Circulatory system", "Nervous system"], "tip": "Message, pull, lever or delivery?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 6, "n": 6, "ans": ["Regular exercise", "Inactivity", "Regular exercise", "Inactivity", "Regular exercise", "Inactivity"], "tip": "Use it or lose it."}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 3, "pts": [["no weight", "weightless", "gravity", "no load", "not used"], ["bone", "muscle", "lose", "weaker", "density"], ["exercise", "stress", "load", "maintain", "keep", "build"]], "tips": ["Without gravity, are bones and muscles used?"]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q5", "max": 3, "pts": [["back pain", "shoulder pain", "posture", "spine", "curve", "strain"], ["muscle", "ligament", "uneven", "one side", "neck", "joint"], ["both straps", "two straps", "lighter", "locker", "wheels", "less books", "fewer books"]], "tips": ["One side carries all the load."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 4, "pts": [["decrease", "fall", "fewer", "goes down", "drops"], ["22"], ["42"], ["lactic acid", "fatigue", "anaerobic", "oxygen"]], "tips": ["Trend, (52 − 30) ÷ 52 × 100, then explain."]}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 2, "pts": [["repeat", "more students", "more people", "mean", "average"], ["same peg", "same hand", "same", "timer", "stopwatch", "rest", "count accurately", "partner counts"]], "tips": ["More data; fair conditions."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 4, "pts": [["bone", "muscle", "joint", "heart", "lungs", "fitness", "strong", "denser"], ["wellbeing", "concentration", "mood", "stress", "healthy", "obesity", "focus", "learning"], ["time", "exams", "less learning", "lesson", "injury", "counter"], ["i think", "overall", "conclusion", "should", "because", "therefore"]], "tips": ["Evidence → benefit to wellbeing → counter-argument → conclusion."]}]}, "models": {"1": [["Q1", "The nervous system (eyes and brain decide, motor neurons send impulses), the muscular system (arm and shoulder muscles contract), the skeletal system (bones as levers moving at the shoulder and elbow joints), and the respiratory and circulatory systems (oxygen and glucose for the muscles)."], ["Q2", "Impulses and balance: nervous. Pulling: muscular. Levers: skeletal. Delivery: circulatory."]], "2": [["Q3", "Exercise strengthens bones, muscles and joints; inactivity weakens them."], ["Q4", "In weightlessness the bones and muscles do not have to support the body's weight, so they are not used [1]; bone loses calcium and density and the muscles shrink [1]; exercise puts load on them so that they keep their strength [1]."]], "3": [["Q5", "The spine may curve to one side and the student may get back and shoulder pain [1]; the muscles and ligaments on one side are strained unevenly [1]; using both straps, a lighter bag or a school locker reduces the strain [1]."]], "4": [["Q6", "The number of squeezes decreases in each period [1]; the decrease is 52 − 30 = 22 squeezes [1], and 22 ÷ 52 × 100 = 42% [1]; the muscles cannot get enough oxygen, respire anaerobically and lactic acid builds up, causing fatigue [1]."], ["Q7", "Repeat with more students and calculate a mean [1]; use the same peg and the same hand, with a partner timing accurately with a stopwatch [1]."]], "5": [["Q8", "Regular activity makes bones denser and muscles, heart and lungs stronger [1]; it also improves concentration, mood and wellbeing and reduces obesity [1]; however, some may argue it takes time away from exam subjects [1]; overall I think the school should make the change, because healthy, active students learn better [1]."]], "6": [["Exit ticket", "Bones become denser and muscles become larger and stronger (joints stay more flexible)."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q4", "q3_0": "Q5", "q4_0": "Q6", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "4532e499-a67c-5a92-b713-9c9c16ce7f67", "ext": "G9-BIO-BODY-L16", "title": "Biology · Body systems · Lesson 16: Homeostasis and negative feedback", "summary": "MYP 4 · Biology · Body systems", "url": "/g9-bio-body-16/", "max": 29, "sort": 26, "msort": 102, "csort": 29, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 5, "n": 5, "ans": ["Yes, kept constant", "Yes, kept constant", "Yes, kept constant", "No, it varies freely", "No, it varies freely"], "tip": "Internal or external?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 6, "n": 6, "ans": ["Set point", "Receptor", "Coordinator", "Effector", "Effector", "Receptor"], "tip": "Normal value, detector, decider or doer?"}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 2, "pts": [["optimum", "best", "work fastest"], ["denature", "too hot", "slow", "too cold", "shape", "active site"]], "tips": ["What happens to enzymes when it is too hot or too cold?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 5, "n": 5, "ans": ["4th", "1st", "3rd", "5th", "2nd"], "tip": "Change → detect → decide → act → back to normal."}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 2, "pts": [["change", "away from", "too high", "too low", "detect"], ["reverse", "opposite", "back to", "returns", "restore", "set point"]], "tips": ["The response is the opposite of the change."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q7", "max": 4, "n": 4, "ans": ["Nerve impulses", "Hormones", "Hormones", "Nerve impulses"], "tip": "Electrical along neurons, or chemical in the blood?"}, {"kind": "text", "id": "q4_1", "q": "Q8", "max": 2, "pts": [["fast", "quick", "immediate", "nerve"], ["slow", "longer", "whole body", "many cells", "liver", "all cells", "blood"]], "tips": ["Speed and how widespread the effect is."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q9", "max": 3, "pts": [["heat stroke", "hypothermia", "dehydration", "diabetes"], ["too hot", "too cold", "too little water", "glucose", "cannot", "fails", "not controlled", "above", "below"], ["drink", "water", "shade", "clothes", "diet", "insulin", "exercise", "warm", "rest", "hat"]], "tips": ["Name it, explain the failure, prevent it."]}]}, "models": {"1": [["Q1", "Enzymes in our cells work best at about 37 °C. If the body is too hot, enzymes are damaged (denatured); if it is too cold, reactions slow down. Keeping it steady keeps the cells working."], ["Q2", "Temperature, glucose and water inside the body are controlled; the air temperature and what you eat are not."]], "2": [["Q3", "Set point: the normal value. Receptor: detects. Coordinator: decides. Effector: acts."], ["Q4", "Body enzymes work best at their optimum of about 37 °C [1]; if it is too hot they denature (the active site changes shape) and if it is too cold reactions are too slow [1]."]], "3": [["Q5", "Fall → receptors → hypothalamus → shivering → back to 37 °C."], ["Q6", "A change from the set point is detected [1]; the body responds by reversing the change, so the value returns to the set point [1]."]], "4": [["Q7", "Shivering and sweating: nerve impulses. Insulin and ADH: hormones."], ["Q8", "A change in temperature needs a fast response, which nerve impulses give [1]; glucose control must act on cells all over the body (especially the liver) for a longer time, which hormones carried in the blood do [1]."]], "5": [["Q9", "Heat stroke [1]: in very hot conditions the body cannot lose heat fast enough, so its temperature rises far above 37 °C and enzymes are damaged [1]; drinking water, resting in the shade and wearing light clothes help prevent it [1]."]], "6": [["Exit ticket", "Homeostasis is keeping the internal environment constant; the hypothalamus controls body temperature."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q4", "q3_1": "Q6", "q4_1": "Q8", "q5_0": "Q9", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "06ddf5b3-8bc7-57e9-a47e-6c8303a75325", "ext": "G9-BIO-BODY-L17", "title": "Biology · Body systems · Lesson 17: Controlling body temperature", "summary": "MYP 4 · Biology · Body systems", "url": "/g9-bio-body-17/", "max": 27, "sort": 27, "msort": 103, "csort": 30, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 6, "n": 6, "ans": ["Response to being too hot", "Response to being too cold", "Response to being too hot", "Response to being too cold", "Response to being too cold", "Response to being too hot"], "tip": "Does it lose heat or keep heat?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 3, "pts": [["receptor", "thermoreceptor"], ["hypothalamus", "brain"], ["impulse", "nerve", "neuron"]], "tips": ["Receptor → coordinator → message."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 4, "pts": [["sweat", "sweat glands"], ["evaporat", "heat energy", "takes heat"], ["vasodilation", "arterioles widen", "blood vessels widen", "dilate"], ["more blood", "surface", "skin", "radiation", "more heat lost", "lose heat"]], "tips": ["Two mechanisms, each with how it works."]}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["humid", "moist air", "water vapour", "already wet", "moisture"], ["evaporat", "less evaporation", "slower"]], "tips": ["What has to happen to sweat for it to cool you?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 4, "pts": [["shiver", "muscles contract"], ["respir", "release heat", "heat", "energy"], ["vasoconstriction", "arterioles narrow", "blood vessels narrow", "constrict"], ["less blood", "less heat lost", "reduce heat loss", "surface", "keep heat"]], "tips": ["A response that makes heat, and one that saves heat."]}, {"kind": "choice", "id": "q4_1", "q": "Q7", "max": 4, "n": 4, "ans": ["Wrong", "Correct", "Correct", "Wrong"], "tip": "Blood vessels do not move; they widen or narrow."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 4, "pts": [["rose", "increase", "went up", "peak"], ["0.5"], ["sweat", "sweat rate", "evaporat"], ["negative feedback", "hypothalamus", "back towards", "returns", "restore", "reverse"]], "tips": ["Up, then down. Why down?"]}]}, "models": {"1": [["Q1", "After running: red face, sweating, feeling hot. When cold: pale skin, shivering, goosebumps. These are the body's responses to cool down or warm up."], ["Q2", "Sweating, vasodilation and red skin lose heat; shivering, vasoconstriction and goosebumps keep or make heat."]], "2": [["Q3", "Thermoreceptors in the skin and the hypothalamus detect the rise in temperature [1]; the hypothalamus compares it with the set point [1]; it sends nerve impulses to the sweat glands and skin arterioles [1]."]], "3": [["Q4", "Sweat glands release sweat onto the skin [1]; the water evaporates, taking heat energy from the skin [1]; in vasodilation the arterioles supplying the skin widen [1], so more blood flows near the surface and more heat is lost by radiation [1]."], ["Q5", "Humid air already holds a lot of water vapour [1], so sweat evaporates more slowly and less heat is removed from the skin [1]."]], "4": [["Q6", "Muscles shiver, contracting and relaxing quickly [1]; this increases respiration, which releases heat [1]; vasoconstriction narrows the arterioles supplying the skin [1], so less blood flows near the surface and less heat is lost [1]."], ["Q7", "Blood vessels do not move; the arterioles widen (vasodilation). Shivering makes heat. Sweating cools."]], "5": [["Q8", "The core temperature rose from 37.0 °C to a peak of 37.5 °C at 20 minutes, then fell [1]; the maximum rise was 0.5 °C [1]; the sweat rate increased so more sweat evaporated, removing heat [1]; this is negative feedback: the hypothalamus detected the rise and the response brought the temperature back towards 37 °C [1]."]], "6": [["Exit ticket", "Vasodilation: the arterioles supplying the skin widen, so more blood flows near the surface to lose heat."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q3", "q3_0": "Q4", "q3_1": "Q5", "q4_0": "Q6", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "f16545aa-dcb6-55c1-a00e-118c14143a0d", "ext": "G9-BIO-BODY-L18", "title": "Biology · Body systems · Lesson 18: Controlling blood sugar and water content", "summary": "MYP 4 · Biology · Body systems", "url": "/g9-bio-body-18/", "max": 31, "sort": 28, "msort": 104, "csort": 31, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 6, "n": 6, "ans": ["Insulin", "Glucagon", "Insulin", "Glucagon", "Insulin", "Glucagon"], "tip": "Insulin: in, into storage. Glucagon: glucose gone, release it."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 4, "pts": [["rise", "increase", "high"], ["pancreas", "detect"], ["insulin"], ["glycogen", "liver", "take up", "cells absorb", "store"]], "tips": ["Detection → hormone → effect."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 6, "n": 6, "ans": ["Type 1", "Type 2", "Type 2", "Type 1", "Type 1", "Type 2"], "tip": "No insulin, or insulin not working?"}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 3, "pts": [["no insulin", "does not make", "cannot make", "little insulin"], ["high", "rise", "glucose stays", "cannot lower", "too high"], ["too low", "right dose", "how much", "dose", "hypo", "balance", "adjust"]], "tips": ["What is missing, and what could go wrong?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 4, "n": 4, "ans": ["More ADH released", "Less ADH released", "More ADH released", "Less ADH released"], "tip": "ADH saves water."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 4, "pts": [["too little water", "less water", "dehydrat", "water content falls", "concentrated"], ["hypothalamus", "detect"], ["pituitary", "adh"], ["reabsorb", "kidney", "less urine", "concentrated urine", "small volume"]], "tips": ["Detection → gland → hormone → kidney."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 4, "pts": [["exercise", "active", "sport", "walk", "pe", "cycle"], ["diet", "sugar", "tax", "whole grain", "vegetables", "healthy food", "label"], ["weight", "obesity", "insulin", "respond", "glucose", "less sugar", "cells"], ["cost", "afford", "habit", "culture", "time", "access", "expensive", "difficult", "difficulty"]], "tips": ["Two actions, how they help, one difficulty."]}]}, "models": {"1": [["Q1", "Their blood glucose has fallen low, so their cells, especially brain and muscle cells, do not have enough glucose for respiration, so they feel weak and shaky."], ["Q2", "Insulin lowers glucose by storing it as glycogen; glucagon raises glucose by breaking down glycogen."]], "2": [["Q3", "Blood glucose rises after the meal [1]; the pancreas detects the rise [1] and releases insulin into the blood [1]; insulin makes cells take up glucose and the liver store it as glycogen, so the level falls to normal [1]."]], "3": [["Q4", "Type 1: no insulin, childhood, injections. Type 2: cells resist insulin, obesity, diet and exercise."], ["Q5", "Their pancreas makes little or no insulin [1], so their blood glucose would stay too high after meals [1]; they measure it to choose the right dose, because too much insulin makes the glucose fall dangerously low [1]."]], "4": [["Q6", "Short of water: more ADH, concentrated urine. Too much water: less ADH, dilute urine."], ["Q7", "The water content of the blood falls because of sweating [1]; the hypothalamus detects this [1]; the pituitary gland releases more ADH [1]; ADH makes the kidneys reabsorb more water, so a small volume of concentrated urine is made and the water content returns to normal [1]."]], "5": [["Q8", "Encourage daily physical activity, for example walking or cycling to school and PE every day [1]; and a tax on sugary drinks with clear food labels to improve diets [1]; both reduce obesity, so body cells respond better to insulin and blood glucose stays normal [1]; a difficulty is that healthy food costs more and habits are hard to change [1]."]], "6": [["Exit ticket", "Insulin, made by the pancreas."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q3", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}], "quizzes": [{"id": "5353ad28-9a97-5384-baf2-f42e321e355d", "title": "Grade 9 · Biology · Body systems · Lesson 1: The respiratory system: parts and their jobs · Criteria A and D exam-style questions", "instr": "Exam-style questions for the lesson \"The respiratory system: parts and their jobs\" (MYP 4, Grade 9 Biology). Criterion A: Knowing and understanding. Criterion D: Reflecting on the impacts of science. 11 marks. Do the lesson first. Written answers are marked against the mark scheme and you get detailed feedback; your teacher checks every mark."}, {"id": "e4b12f2c-94f3-5f6c-adca-5dee3c588a3b", "title": "Grade 9 · Biology · Body systems · Lesson 2: Gas exchange in the alveoli: form and function · Criteria A and C exam-style questions", "instr": "Exam-style questions for the lesson \"Gas exchange in the alveoli: form and function\" (MYP 4, Grade 9 Biology). Criterion A: Knowing and understanding. Criterion C: Processing and evaluating. 12 marks. Do the lesson first. Written answers are marked against the mark scheme and you get detailed feedback; your teacher checks every mark."}, {"id": "8fea4ef4-f2cc-5cfb-a782-916e616e94da", "title": "Grade 9 · Biology · Body systems · Lesson 3: Ventilation: the muscles of breathing in and out · Criteria